import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"2026-11 验收报告","description":"2026-11 的测试矩阵、手动检查、未完成项和回退说明；含 0.2.0 历史快照与 0.3.4 验证补充。","frontmatter":{"title":"2026-11 验收报告","description":"2026-11 的测试矩阵、手动检查、未完成项和回退说明；含 0.2.0 历史快照与 0.3.4 验证补充。","outline":[2,3]},"headers":[],"relativePath":"delivery/acceptance-2026-11.md","filePath":"delivery/acceptance-2026-11.md","lastUpdated":1795426969000}'),a={name:"delivery/acceptance-2026-11.md"};function c(i,t,n,l,s,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="_2026-11-验收报告" tabindex="-1">2026-11 验收报告 <a class="header-anchor" href="#_2026-11-验收报告" aria-label="Permalink to &quot;2026-11 验收报告&quot;">​</a></h1><p>日期：2026-11-23（0.3.4 补充）；原报告日期 2026-11-20，目标版本 <code>0.2.0</code>。范围：把 Hearth 推进到可日常使用、可回退、可对外证明，并用自动测试和真实构建验证。</p><h2 id="_0-3-4-补充-2026-11-23" tabindex="-1">0.3.4 补充（2026-11-23） <a class="header-anchor" href="#_0-3-4-补充-2026-11-23" aria-label="Permalink to &quot;0.3.4 补充（2026-11-23）&quot;">​</a></h2><p><strong>结论：</strong> 代码与自动验证通过，0.3.4 安装包与便携包已发布；真实账户、自动更新签名与干净机卸载重装仍未验收。</p><table tabindex="0"><thead><tr><th>项目</th><th>命令</th><th>结果</th></tr></thead><tbody><tr><td>版本一致</td><td><code>npm run version:check</code></td><td>0.3.4：7 个 workspace + Cargo + Tauri + lockfile</td></tr><tr><td>类型检查</td><td><code>npm run typecheck</code></td><td>0 错误</td></tr><tr><td>单元/集成</td><td><code>npm test</code></td><td>140 个文件、946 个用例（931 通过、15 跳过）</td></tr><tr><td>长跑矩阵</td><td><code>npm run test:longrun</code></td><td>18/18 通过</td></tr><tr><td>Web 构建</td><td><code>npm run build</code></td><td>通过（JS 643.06 kB / CSS 158.97 kB）</td></tr><tr><td>文档构建</td><td><code>npm run docs:build</code></td><td>通过，无死链</td></tr><tr><td>首跑离线自检</td><td><code>npm run first:run -- --fake</code></td><td>通过</td></tr><tr><td>Windows 沙箱</td><td><code>npm run test:sandbox</code></td><td>12 项真实测试通过</td></tr><tr><td>0.3.4 安装包</td><td><code>npm run release:build</code></td><td>NSIS 30.5 MiB、便携 zip 47.2 MiB，已发布 Pre-release</td></tr></tbody></table><p>本版新增的验证重点是崩溃恢复而不是新功能：<code>after-prepare</code>、<code>after-dispatch</code>、<code>mid-tool</code>、<code>after-settle</code>、<code>after-checkpoint</code>、<code>after-cleanup</code> 六个崩溃点各重复 3 次；每个终态 run 输出 <code>run-evidence.json</code>，包含 checkpoint 引用、恢复决策、operations/cleanup、artifacts 和 run 链。</p><p>仍未验收：自动更新签名、Windows Authenticode、干净机安装/卸载与升级、真实飞书/SMTP/IMAP 账户、真实模型首跑，以及数周真实使用中的断电/蓝屏恢复演练。0.2.0 及其后续 0.3.3 的下列内容保留为历史记录，不再改写。</p><h2 id="结论-0-2-0-历史快照" tabindex="-1">结论（0.2.0 历史快照） <a class="header-anchor" href="#结论-0-2-0-历史快照" aria-label="Permalink to &quot;结论（0.2.0 历史快照）&quot;">​</a></h2><p><strong>代码与自动验证完成；真实用户验收未全部完成。</strong> 本轮新增的可信执行、浏览器、项目档案、首次任务验证、监督收件箱、自用报告、自动更新和发布脚本均已进入 <code>main</code>，782 个自动测试和 18 项离线 UI 端到端通过。真实模型首跑因当前 key 无权限失败，已签名更新和干净机安装未执行，因此不能宣称“装完就能用”已经对真实用户验收。</p><h2 id="测试矩阵" tabindex="-1">测试矩阵 <a class="header-anchor" href="#测试矩阵" aria-label="Permalink to &quot;测试矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>命令</th><th>结果</th></tr></thead><tbody><tr><td>类型检查</td><td><code>npm run typecheck</code></td><td>0 error</td></tr><tr><td>单元/集成</td><td><code>npm test</code></td><td>110 个文件、782 个用例全部通过</td></tr><tr><td>Web 构建</td><td><code>npm run build</code></td><td>通过，JS 723.79 kB / CSS 130.23 kB</td></tr><tr><td>文档构建</td><td><code>npm run docs:build</code></td><td>通过，无死链</td></tr><tr><td>浏览器 fixture</td><td><code>npm run test:browser</code></td><td>12 项检查通过，18 个证据文件</td></tr><tr><td>UI 端到端</td><td><code>HEARTH_E2E_OFFLINE=1 npm run test:e2e</code></td><td>18 项通过，0 失败</td></tr><tr><td>Tauri updater 编译</td><td><code>cargo check --manifest-path apps/desktop-tauri/src-tauri/Cargo.toml --features updater</code></td><td>通过</td></tr><tr><td>Tauri 配置构建</td><td><code>npx tauri build --debug --no-bundle --features updater --config &lt;overlay&gt;</code></td><td>通过</td></tr><tr><td>0.2.0 安装包</td><td><code>npm run release:build</code></td><td>通过；NSIS 安装包 30.5 MiB，内置 <code>server.mjs</code> 启动后 <code>/api/ready</code> 返回 200</td></tr><tr><td>发布整理</td><td><code>npm run release:prepare -- --skip-build</code></td><td>通过；安装包、47.1 MiB 便携 zip（3,450 个文件）、发布说明和 SHA256 校验和</td></tr></tbody></table><p>UI 端到端覆盖：首次向导跳过、聊天壳、会话操作、连接状态、导航、需要你收件箱、逐轮接口空状态与 rewind 错误、缺失模型首跑保护、IME、会话切换/删除、执行器设置、模型密钥遮罩、任务详情标签、窄视口和浏览器控制台错误。浏览器 fixture 覆盖打开/读取/输入/上传/危险点击拒绝/断言/配方/提交/下载/双标签/暂停恢复/完成门禁/证据文件。</p><h2 id="手动检查" tabindex="-1">手动检查 <a class="header-anchor" href="#手动检查" aria-label="Permalink to &quot;手动检查&quot;">​</a></h2><ul><li><strong>Chrome 真实启动：</strong> 使用 <code>C:\\Users\\Jason\\AppData\\Local\\Google\\Chrome\\Application\\chrome.exe</code>，独立 profile 启动成功，标题 <code>Hearth smoke</code>，引擎 <code>chrome</code>。</li><li><strong>发布产物：</strong> <code>release/0.2.0/</code> 生成 30.5 MiB NSIS 安装包、47.1 MiB 便携 zip（3,450 个文件）、<code>RELEASE_NOTES.md</code> 和 <code>SHA256SUMS.txt</code>；便携 zip 内保持 <code>Hearth.exe</code> 与 <code>resources/</code> 同级。用打包后的 <code>resources/server/server.mjs</code> 启动独立服务，<code>/api/ready</code> 返回 <code>{&quot;ok&quot;:true,&quot;name&quot;:&quot;Hearth&quot;}</code>；打包后的 ACL sandbox 包可以正常导入。</li><li><strong>构建修复：</strong> Playwright 的未声明 BiDi 依赖在打包时被替换为惰性桩，不影响 Chromium CDP 路径；sandbox 依赖改为扁平 <code>node_modules</code>，最长路径从 300+ 字符降到 167 字符，满足 makensis 限制。Tauri 构建前会清空 <code>target/release/resources</code>，避免旧的 <code>server/node_modules</code> 残留进入安装包（清理前暂存目录为 391 MiB / 29,695 文件）。</li><li><strong>自用报告：</strong> 本机 30 天事件账本汇总 341 个任务、290 个完成、24 个失败或可恢复，成功率 92.4%，一次通过率与 token 汇总同时生成。该数据包含历史任务，只说明本机使用，不作为 v0.2 质量证明。</li><li><strong>Tauri 签名禁用路径：</strong> 三项签名变量不全时构建脚本打印警告并继续普通构建，不生成 <code>.sig</code> 或 <code>latest.json</code>。</li></ul><h2 id="未完成" tabindex="-1">未完成 <a class="header-anchor" href="#未完成" aria-label="Permalink to &quot;未完成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>原因</th><th>影响</th></tr></thead><tbody><tr><td>真实模型首跑</td><td>当前 key 调用 <code>deepseek-v4.1-flash-1017</code> 返回 <code>Access to model denied</code></td><td>首次任务验证代码有 fake-runner 测试，但没有可用模型的真实成功记录</td></tr><tr><td>日常 Chrome 扩展桥</td><td>本轮未实现 MV3 扩展；独立 profile 需要首次登录</td><td>不能直接接管用户默认 Chrome 的已登录会话</td></tr><tr><td>签名自动更新</td><td>缺少签名私钥、公钥和发布地址</td><td>只能发布手动更新包，不能验证旧版本自动升级</td></tr><tr><td>干净机安装/卸载</td><td>未准备全新 Windows 用户环境</td><td>安装器行为、SmartScreen、卸载残留未验收</td></tr><tr><td>真实账户/设备</td><td>没有飞书租户、SMTP/IMAP 账户和配对设备</td><td>相关能力只有本地测试闭环</td></tr><tr><td>Windows 代码签名</td><td>没有 Authenticode 证书</td><td>安装包会触发 SmartScreen 警告</td></tr></tbody></table><h2 id="回退" tabindex="-1">回退 <a class="header-anchor" href="#回退" aria-label="Permalink to &quot;回退&quot;">​</a></h2><ul><li>代码回退：<code>git revert &lt;commit&gt;</code>；本轮按闭环拆分提交，可按功能单独回退。</li><li>任务文件回退：任务详情逐轮时间线点“回退”，默认拒绝覆盖用户手改；需要强制时使用 <code>force</code> 并留事件。</li><li>数据库：升级前按设置页“数据与备份”创建加密备份；恢复是回滚式事务，失败不留下半恢复状态。</li><li>发布：删除 <code>release/&lt;version&gt;/</code> 和对应上传文件；自动更新回退需要发布一个更高版本，不能把客户端降到旧版。</li></ul><h2 id="引用" tabindex="-1">引用 <a class="header-anchor" href="#引用" aria-label="Permalink to &quot;引用&quot;">​</a></h2><ul><li>当前能力与留空项：<a href="/hearth-os/delivery/status.html">当前交付状态</a></li><li>浏览器设计与边界：<a href="/hearth-os/design/browser.html">浏览器自动化</a></li><li>日常使用与自用报告：<a href="/hearth-os/reference/daily-use.html">日常使用</a></li><li>发版流程：<a href="/hearth-os/reference/releasing.html">构建、签名与发版</a></li><li>历史 Native 30 题评测：<a href="/hearth-os/evaluation/">评测与结果</a></li></ul>',20)])])}const m=e(a,[["render",c]]);export{p as __pageData,m as default};
